import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { createTunnel } from '@volter/tunnel/client';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// the Harness's local server, on loopback
const local = createServer((request, response) => {
  const chunks = [];
  request.on('data', (chunk) => chunks.push(chunk));
  request.on('end', () => {
    response.writeHead(200, { 'content-type': 'application/json' });
    response.end(JSON.stringify({ method: request.method, path: request.url, host: request.headers['x-forwarded-host'] ?? request.headers.host, body: Buffer.concat(chunks).toString() }));
  });
});
await new Promise((resolve) => local.listen(0, '127.0.0.1', resolve));
// Volter Harness's stable relay (sdk/remote-access/index.mjs startStableTunnel), as it calls the client
const relay = (process.env.SUPERCODE_TUNNEL_SERVER_URL ?? process.env.TUNNEL_SERVER_URL)?.trim();
if (!relay) throw new Error('Set SUPERCODE_TUNNEL_SERVER_URL before using the stable relay.');
const tunnel = await createTunnel({
  authRequired: false,
  host: relay,
  port: local.address().port,
  ...(process.env.TUNNEL_SECRET ? { secret: process.env.TUNNEL_SECRET } : {}),
  tunnelId: 'ada-harness',
});
try {
  const publicOrigin = new URL(tunnel.url).origin;
  assert.equal(publicOrigin, 'https://ada-harness.voltertest.xyz');
  // a person opens the shared remote-access URL: the request reaches the local server through the control socket
  const opened = await fetch(publicOrigin + '/sessions?view=board', { method: 'POST', headers: { 'content-type': 'text/plain' }, body: 'open the board' });
  assert.equal(opened.status, 200);
  const seen = await opened.json();
  assert.deepEqual(seen, { method: 'POST', path: '/sessions?view=board', host: 'ada-harness.voltertest.xyz', body: 'open the board' });
  console.log(JSON.stringify({ shared: publicOrigin, seen }));
} finally {
  tunnel.close();
  local.close();
}
